/* The stitch: a gold running-stitch line the nav hangs off — the one thing to remember */

:where(body.customer-account[data-ui="unified"]) .cp-nav { position: relative; display: flex; flex-direction: column; gap: 3px; padding-left: 22px; margin-top: 6px; }

:where(body.customer-account[data-ui="unified"]) .cp-nav::before {
