}

:where(body.customer-account[data-ui="unified"]) .cp-nav a[aria-current="page"]::before { opacity: 1; transform: scale(1); }

:where(body.customer-account[data-ui="unified"]) .cp-nav .cp-icon { width: 19px; height: 19px; opacity: .85; }

:where(body.customer-account[data-ui="unified"]) .cp-nav-badge {
