:where(body.customer-account[data-ui="unified"]) .cp-side-rep-label { font-size: 10.5px; letter-spacing: .12em; text-transform: uppercase; color: var(--color-on-brand); font-weight: 700; }

:where(body.customer-account[data-ui="unified"]) .cp-side-rep-name { font-weight: 600; color: var(--color-on-brand); font-size: 14px; line-height: 1.2; }

