}
.pp-hero-img img { width: 100%; height: 100%; object-fit: contain; }

/* Thumbnail strip — one per available angle (Model front/back/side + Flat front/back) */
.pp-thumbs { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }

.pp-thumb {
