.pp-section {
    background: var(--cp-surface); border: 1px solid var(--cp-border); border-radius: var(--cp-radius);
    box-shadow: var(--cp-shadow-1); padding: 16px 18px; margin-top: 18px;
}
.pp-section h2 { font-size: 16px; font-weight: 700; color: var(--cp-ink); margin: 0 0 4px; }
.pp-section-sub { font-size: 12.5px; color: var(--cp-ink-soft); margin: 0 0 12px; }
.pp-desc { font-size: 13.5px; color: var(--cp-ink-soft); line-height: 1.6; margin: 6px 0 0; }

/* Ordered color × size matrix */
.pp-mx-wrap { overflow-x: auto; }
.pp-mx { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.pp-mx th, .pp-mx td { border: 1px solid var(--cp-border-soft); padding: 7px 6px; text-align: center; }
.pp-mx thead th { color: var(--cp-ink-soft); font-weight: 700; background: var(--cp-zebra); }
.pp-mx th.pp-mx-c, .pp-mx td.pp-mx-c { text-align: left; white-space: nowrap; }
.pp-mx td.pp-mx-c { display: table-cell; }
.pp-mx .cp-swatch { vertical-align: middle; margin-right: 7px; }
.pp-mx-total { font-weight: 700; color: var(--cp-theme-dark); }

/* Order history */
.pp-hist { display: flex; flex-direction: column; }
.pp-hist-row { display: flex; justify-content: space-between; gap: 12px; padding: 8px 0; border-bottom: 1px solid var(--cp-border-soft); }
.pp-hist-row:last-child { border-bottom: 0; }
.pp-hist-main { font-size: 13.5px; color: var(--cp-ink); }
.pp-hist-sub { font-size: 12.5px; color: var(--cp-ink-soft); text-align: right; white-space: nowrap; }

/* Re-order panel */
.pp-reorder .cp-size-grid { margin-top: 2px; }
.pp-field { display: block; margin: 12px 0; }
.pp-flabel { display: block; font-size: 13px; font-weight: 600; color: var(--gray-700); margin-bottom: 6px; }
.pp-flabel small { font-weight: 400; color: var(--print-line); }

.pp-reorder textarea {
    width: 100%; padding: 9px 11px; border: 1px solid var(--gray-300); border-radius: 8px;
    font-size: 14px; font-family: inherit; resize: vertical;
}
.pp-reorder textarea:focus { outline: none; border-color: var(--cp-theme); box-shadow: 0 0 0 3px rgb(46 125 50 / 12%); }
.pp-req-error { color: var(--red-700); font-size: 13px; min-height: 1em; margin-bottom: 6px; }
.pp-req-actions { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }

.pp-addlist-btn {
    background: var(--cp-surface); color: var(--cp-theme-dark); border: 1px solid var(--cp-theme-light);
    border-radius: 8px; padding: 11px 16px; font-size: 14px; font-weight: 600; font-family: inherit; cursor: pointer;
    transition: background .12s, border-color .12s;
}
.pp-addlist-btn:hover { background: var(--cp-theme-bg); border-color: var(--cp-theme); }

/* Decoration-method picker (re-order) — defaulted from history; enforces the API minimum, no price */
.pp-methods { display: flex; flex-wrap: wrap; gap: 8px; }

.pp-method {
    position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 1px;
    padding: 8px 13px; min-width: 96px; border: 1px solid var(--cp-border); border-radius: var(--cp-radius-sm);
    background: var(--cp-surface); cursor: pointer; font-family: inherit; text-align: left; transition: border-color .12s;
}
.pp-method:hover { border-color: var(--cp-theme-light); }
.pp-method.is-selected { border: 2px solid var(--cp-theme); padding: 7px 12px; background: var(--cp-theme-bg); }
.pp-method-nm { font-size: 13.5px; font-weight: 700; color: var(--cp-ink); }
.pp-method-hint { font-size: 11px; color: var(--cp-ink-mute); }

.pp-method-tag {
    position: absolute; top: -8px; right: 8px; font-size: 9px; font-weight: 700; letter-spacing: .02em;
    background: var(--cp-theme); color: var(--color-on-brand); padding: 1px 6px; border-radius: 999px;
}
.pp-method-note { flex-basis: 100%; font-size: 12px; color: var(--bs-warning-ink); margin-top: 4px; }
.pp-method-min { font-size: 12.5px; line-height: 1.5; margin-top: 8px; }

.pp-method-min--warn {
    display: flex; gap: 8px; align-items: flex-start; color: var(--bs-warning-ink);
    background: var(--store-rush-soft); border: 1px solid var(--amber-200); border-radius: var(--cp-radius-sm); padding: 9px 11px;
}
