.pp-up-banner { border-radius: var(--cp-radius-sm); overflow: hidden; margin: 6px 0 14px; }
.pp-up-banner img { width: 100%; height: auto; display: block; max-height: 260px; object-fit: cover; }
.pp-up-card { border: 1px solid var(--cp-border); border-radius: var(--cp-radius); padding: 14px; margin-top: 12px; background: var(--cp-cream); }
.pp-up-top { display: flex; gap: 14px; align-items: flex-start; }
.pp-up-img { flex: 0 0 96px; width: 96px; height: 108px; background: var(--cp-surface); border: 1px solid var(--cp-border); border-radius: var(--cp-radius-sm); overflow: hidden; display: flex; align-items: center; justify-content: center; }
.pp-up-img img { width: 100%; height: 100%; object-fit: contain; }
.pp-up-info { flex: 1; min-width: 0; }
.pp-up-tier { display: inline-block; font-size: 11px; font-weight: 700; color: var(--cp-theme-dark); background: var(--cp-theme-bg); border: 1px solid var(--cp-theme-light); padding: 1px 8px; border-radius: 999px; margin-bottom: 4px; }
.pp-up-name { font-size: 15px; font-weight: 700; color: var(--cp-ink); line-height: 1.3; }
.pp-up-brand { font-size: 12px; color: var(--cp-ink-mute); }
.pp-up-blurb { font-size: 13px; color: var(--cp-ink-soft); line-height: 1.5; margin: 5px 0 0; }
.pp-up-swatches { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 8px; }
.pp-up-digit { display: flex; gap: 9px; align-items: flex-start; margin: 12px 0; font-size: 12.5px; color: var(--cp-theme-dark); background: var(--cp-theme-bg); border: 1px solid var(--cp-theme-light); border-radius: var(--cp-radius-sm); padding: 10px 12px; line-height: 1.5; }
.pp-up-digit i { font-style: normal; font-size: 17px; }
