.pp-up-mxload, .pp-up-mxnote { font-size: 12.5px; color: var(--cp-ink-mute); padding: 6px 0; }
.pp-up-mxtitle { font-size: 12.5px; font-weight: 700; color: var(--cp-ink); margin-bottom: 6px; }
.pp-up-mxwrap { overflow-x: auto; }
.pp-up-mxtable { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.pp-up-mxtable th, .pp-up-mxtable td { border: 1px solid var(--cp-border-soft); padding: 6px 8px; text-align: center; }
.pp-up-mxtable th.lbl, .pp-up-mxtable td.lbl { text-align: left; color: var(--cp-ink-soft); }
.pp-up-mxtable thead th { background: var(--cp-zebra); color: var(--cp-ink-soft); font-weight: 700; }
.pp-up-mxtable td.warn { color: var(--bs-warning-ink); }
.pp-up-mxfoot { font-size: 11px; color: var(--cp-ink-mute); margin-top: 6px; line-height: 1.5; }
.pp-up-btn { margin-top: 8px; }
.pp-req-hint { font-weight: 400; font-size: 12px; color: var(--cp-ink-mute); }
.pp-up-order { border-top: 1px solid var(--cp-border-soft); margin-top: 12px; padding-top: 12px; }
.pp-up-colorrow { font-size: 13px; color: var(--cp-ink); margin-bottom: 8px; }
.pp-up-colors { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 12px; }
