.pp-quicklinks { display: flex; flex-wrap: wrap; gap: 8px; margin: 0 0 16px; }

.pp-ql {
    display: inline-flex; align-items: center; font-size: 12.5px; font-weight: 600; text-decoration: none;
    padding: 6px 13px; border-radius: 999px; background: var(--cp-surface-2); color: var(--cp-ink);
