/* ==========================================================================
   portal-reorder-list.css — shared multi-item "Re-order List" (floating button
   + slide-in drawer). Loaded on the product page AND the portal home. Uses the
   portal theme tokens (--cp-*) with plain fallbacks so it works on either page.
   ========================================================================== */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue so the page
   keeps its exact look. Map them to shared_components/css/tokens.css names when the page is redesigned;
   every rule below uses var(). Raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --portal-reorder-list-gray: #888;
    --portal-reorder-list-gray-2: #5c6b5e;
}
/* stylelint-enable color-no-hex */

.rl-fab {
    display: inline-flex;
    position: fixed; right: 18px; bottom: 18px; z-index: 1000;
    align-items: center; gap: 8px;
    background: var(--cp-theme, var(--store-green-700)); color: var(--color-on-brand); border: none; border-radius: 999px;
    padding: 12px 18px; font-size: 14px; font-weight: 700; font-family: inherit; cursor: pointer;
    box-shadow: 0 4px 16px rgb(0 0 0 / 22%);
}
.rl-fab:hover { filter: brightness(1.05); }

.rl-fab-badge {
    background: var(--color-surface); color: var(--cp-theme-dark, var(--material-green-900)); border-radius: 999px;
    padding: 1px 8px; font-size: 12px; font-weight: 800;
}

.rl-drawer { position: fixed; inset: 0; z-index: 1001; background: rgb(0 0 0 / 40%); display: flex; justify-content: flex-end; }

.rl-panel {
    width: 420px; max-width: 92vw; height: 100%; background: var(--color-surface);
    display: flex; flex-direction: column; padding: 18px; overflow-y: auto;
    box-shadow: -4px 0 24px rgb(0 0 0 / 20%);
}
.rl-head { display: flex; justify-content: space-between; align-items: center; font-size: 17px; font-weight: 700; color: var(--cp-ink, var(--store-green-900)); }
.rl-x { background: none; border: none; font-size: 26px; line-height: 1; cursor: pointer; color: var(--portal-reorder-list-gray); padding: 0 4px; }
.rl-sub { font-size: 12.5px; color: var(--cp-ink-soft, var(--portal-reorder-list-gray-2)); margin: 4px 0 12px; }

.rl-items { flex: 1; display: flex; flex-direction: column; gap: 8px; }
.rl-empty { color: var(--portal-reorder-list-gray); font-size: 14px; padding: 24px 0; text-align: center; }
.rl-item { display: flex; gap: 10px; align-items: center; border: 1px solid var(--cp-border, var(--store-green-100)); border-radius: 10px; padding: 8px; }
.rl-item-img { flex: 0 0 46px; width: 46px; height: 52px; background: var(--cp-surface-2, var(--gray-100)); border-radius: 6px; overflow: hidden; display: flex; align-items: center; justify-content: center; }
.rl-item-img img { width: 100%; height: 100%; object-fit: contain; }
.rl-item-body { flex: 1; min-width: 0; }
.rl-item-t { font-size: 13.5px; font-weight: 700; color: var(--cp-ink, var(--print-ink)); }
.rl-item-s { font-size: 12px; color: var(--cp-ink-soft, var(--portal-reorder-list-gray-2)); }
.rl-item-sz { font-size: 11.5px; color: var(--bs-warning-ink); }
.rl-item-x { background: none; border: none; font-size: 20px; line-height: 1; color: var(--red-700); cursor: pointer; padding: 0 4px; align-self: flex-start; }

.rl-note-l { display: block; font-size: 13px; font-weight: 600; color: var(--gray-700); margin: 12px 0 0; }
.rl-note-l small { font-weight: 400; color: var(--print-line); }

.rl-note-l textarea {
    width: 100%; margin-top: 6px; padding: 9px 11px; border: 1px solid var(--gray-300); border-radius: 8px;
    font-size: 14px; font-family: inherit; resize: vertical;
}
.rl-err { color: var(--red-700); font-size: 13px; min-height: 1em; margin: 6px 0; }

.rl-send {
    background: var(--cp-theme, var(--store-green-700)); color: var(--color-on-brand); border: none; border-radius: 8px;
    padding: 12px; font-size: 15px; font-weight: 700; font-family: inherit; cursor: pointer; margin-top: 8px;
}
.rl-send:disabled { opacity: .6; cursor: default; }
.rl-cont { background: none; border: none; color: var(--cp-theme-dark, var(--material-green-900)); font-size: 13px; font-family: inherit; cursor: pointer; margin-top: 8px; padding: 8px; }

.rl-flash {
    position: fixed; left: 50%; bottom: 24px; transform: translateX(-50%) translateY(20px);
    background: var(--store-green-900); color: var(--color-on-brand); padding: 12px 20px; border-radius: 10px; font-size: 14px;
    opacity: 0; transition: opacity .2s, transform .2s; z-index: 1002; pointer-events: none; max-width: 90vw; text-align: center;
}
.rl-flash.show { opacity: 1; transform: translateX(-50%) translateY(0); }

@media (width <= 480px) { .rl-fab { right: 12px; bottom: 12px; padding: 10px 15px; } }

changes.after:
/* Account-family layouts. Shared tokens and components own the UI primitives. */

@layer components.pages {
/* ==========================================================================
   portal-reorder-list.css — shared multi-item "Re-order List" (floating button
   + slide-in drawer). Loaded on the product page AND the portal home. Uses the
   portal theme tokens (--cp-*) with plain fallbacks so it works on either page.
   ========================================================================== */

:where(body.customer-account[data-ui="unified"]) {
    --portal-reorder-list-gray: var(--ui-muted);
    --portal-reorder-list-gray-2: var(--ui-muted);
}

:where(body.customer-account[data-ui="unified"]) .rl-fab {
    display: inline-flex;
    position: fixed; right: 18px; bottom: 18px; z-index: 1000;
    align-items: center; gap: 8px;
    background: var(--cp-theme, var(--store-green-700)); color: var(--color-on-brand); border: none;
    padding: 12px 18px; font-size: 14px; font-weight: 700; font-family: inherit; cursor: pointer;
    box-shadow: 0 4px 16px rgb(0 0 0 / 22%); border-radius: var(--radius-sm);
}

:where(body.customer-account[data-ui="unified"]) .rl-fab:hover { filter: brightness(1.05); }

:where(body.customer-account[data-ui="unified"]) .rl-fab-badge {
    background: var(--color-surface); color: var(--cp-theme-dark, var(--material-green-900)); border-radius: 999px;
    padding: 1px 8px; font-size: 12px; font-weight: 800;
}

:where(body.customer-account[data-ui="unified"]) .rl-drawer { position: fixed; inset: 0; z-index: 1001; background: rgb(0 0 0 / 40%); display: flex; justify-content: flex-end; }

:where(body.customer-account[data-ui="unified"]) .rl-panel {
    width: 420px; height: 100%; background: var(--color-surface);
    display: flex; flex-direction: column; padding: 18px; overflow-y: auto;
    box-shadow: -4px 0 24px rgb(0 0 0 / 20%); max-width: 100vw;
}

:where(body.customer-account[data-ui="unified"]) .rl-head { display: flex; justify-content: space-between; align-items: center; font-size: 17px; font-weight: 700; color: var(--cp-ink, var(--store-green-900)); }

:where(body.customer-account[data-ui="unified"]) .rl-x { background: none; border: none; font-size: 26px; line-height: 1; cursor: pointer; color: var(--portal-reorder-list-gray); padding: 0 4px; }

:where(body.customer-account[data-ui="unified"]) .rl-sub { font-size: 12.5px; color: var(--cp-ink-soft, var(--portal-reorder-list-gray-2)); margin: 4px 0 12px; }

:where(body.customer-account[data-ui="unified"]) .rl-items { flex: 1; display: flex; flex-direction: column; gap: 8px; }

:where(body.customer-account[data-ui="unified"]) .rl-empty { color: var(--portal-reorder-list-gray); font-size: 14px; padding: 24px 0; text-align: center; }

:where(body.customer-account[data-ui="unified"]) .rl-item { display: flex; gap: 10px; align-items: center; border: 1px solid var(--cp-border, var(--store-green-100)); border-radius: 10px; padding: 8px; }

:where(body.customer-account[data-ui="unified"]) .rl-item-img { flex: 0 0 46px; width: 46px; height: 52px; background: var(--cp-surface-2, var(--gray-100)); border-radius: 6px; overflow: hidden; display: flex; align-items: center; justify-content: center; }

:where(body.customer-account[data-ui="unified"]) .rl-item-img img { width: 100%; height: 100%; object-fit: contain; }

:where(body.customer-account[data-ui="unified"]) .rl-item-body { flex: 1; min-width: 0; }

:where(body.customer-account[data-ui="unified"]) .rl-item-t { font-size: 13.5px; font-weight: 700; color: var(--cp-ink, var(--print-ink)); }

:where(body.customer-account[data-ui="unified"]) .rl-item-s { font-size: 12px; color: var(--cp-ink-soft, var(--portal-reorder-list-gray-2)); }

:where(body.customer-account[data-ui="unified"]) .rl-item-sz { font-size: 11.5px; color: var(--bs-warning-ink); }

:where(body.customer-account[data-ui="unified"]) .rl-item-x { background: none; border: none; font-size: 20px; line-height: 1; color: var(--red-700); cursor: pointer; padding: 0 4px; align-self: flex-start; }

:where(body.customer-account[data-ui="unified"]) .rl-note-l { display: block; font-size: 13px; font-weight: 600; color: var(--gray-700); margin: 12px 0 0; }

:where(body.customer-account[data-ui="unified"]) .rl-note-l small { font-weight: 400; color: var(--ui-muted); }

:where(body.customer-account[data-ui="unified"]) .rl-err { color: var(--red-700); font-size: 13px; min-height: 1em; margin: 6px 0; }

:where(body.customer-account[data-ui="unified"]) .rl-flash {
    position: fixed; left: 50%; bottom: 24px; transform: translateX(-50%) translateY(20px);
    background: var(--store-green-900); color: var(--color-on-brand); padding: 12px 20px; border-radius: 10px; font-size: 14px;
    opacity: 0; transition: opacity .2s, transform .2s; z-index: 1002; pointer-events: none; max-width: 90vw; text-align: center;
}

:where(body.customer-account[data-ui="unified"]) .rl-flash.show { opacity: 1; transform: translateX(-50%) translateY(0); }

@media (width <= 480px) {

:where(body.customer-account[data-ui="unified"]) .rl-fab { right: 12px; bottom: 12px; padding: 10px 15px; } }

:where(body.customer-account[data-ui="unified"]) :is(.rl-x, .rl-item-x) { min-width: 44px; min-height: 44px; }

:where(body.customer-account[data-ui="unified"]) .rl-send { margin-top: 8px; }

:where(body.customer-account[data-ui="unified"]) .rl-cont { margin-top: 8px; }

@media (width <= 1023px) {

:where(body.customer-portal[data-ui="unified"]) .rl-fab { bottom: 84px; } }
}
